-- DarkChaos: normal mobs of maps 750 (81-129) and 751 (130-160) retuned toward 14-second solo fights
-- (generated by tools/balance/gen_zone_tuning.py from damage meter run 2, 2026-11-15)
--
-- Stock level 80 (Northrend) solo fights last 11-12 seconds and cost 0.8% of the player's health per
-- second; on these maps they took 16-33 seconds at up to 1.4%. Per 5-level bucket of mob level,
-- HealthModifier is scaled toward 14-second fights and DamageModifier toward 0.85% health lost per
-- second, by factors between 0.5 and 1 (no mob gets harder). Only rank-0 creatures spawned on one
-- of the two maps and nowhere else are changed; elites, bosses and shared templates are not.
--
-- The factors apply to the modifiers a mob had before this file first ran, which it keeps in
-- dc_balance_mob_tune_backup: re-running gives the same result. To undo, copy the backup's two
-- columns back into creature_template. Apply to acore_world, then restart the worldserver.
--
-- map bucket  fights  seconds  loss%/s  -> health x  damage x
-- 750     80    1401     15.8     0.71       0.886     1.000
-- 750     85     278     17.5     0.72       0.800     1.000
-- 750     90     668     24.8     1.39       0.565     0.612
-- 750     95     141     25.9     1.27       0.541     0.669
-- 750    100      92     18.4     0.64       0.762     1.000
-- 750    105      65     17.6     0.96       0.797     0.888
-- 750    110     158     22.0     0.88       0.636     0.966
-- 750    115      24     22.7     0.87       0.616     0.982
-- 750    120       0     19.3     0.92       0.724     0.929
-- 750    125      13     23.3     0.99       0.602     0.856
-- 751    130     345     21.9     0.90       0.639     0.944
-- 751    135     629     25.0     1.07       0.560     0.794
-- 751    140     678     21.0     1.33       0.667     0.639
-- 751    145     620     18.4     1.35       0.761     0.630
-- 751    150     806     18.8     1.23       0.745     0.691
-- 751    155     448     20.0     1.35       0.700     0.630

CREATE TABLE IF NOT EXISTS `dc_balance_mob_tune_backup` (`entry` INT UNSIGNED NOT NULL PRIMARY KEY, `HealthModifier` FLOAT NOT NULL, `DamageModifier` FLOAT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TEMPORARY TABLE IF EXISTS `dc_tmp_mob_tune`;
CREATE TEMPORARY TABLE `dc_tmp_mob_tune` (`map` SMALLINT UNSIGNED NOT NULL, `bucket` TINYINT UNSIGNED NOT NULL, `hp_factor` FLOAT NOT NULL, `dmg_factor` FLOAT NOT NULL, PRIMARY KEY (`map`, `bucket`)) ENGINE=InnoDB;
DELETE FROM `dc_tmp_mob_tune`;
INSERT INTO `dc_tmp_mob_tune` (`map`, `bucket`, `hp_factor`, `dmg_factor`) VALUES (750, 80, 0.886, 1.000), (750, 85, 0.800, 1.000), (750, 90, 0.565, 0.612), (750, 95, 0.541, 0.669), (750, 100, 0.762, 1.000), (750, 105, 0.797, 0.888), (750, 110, 0.636, 0.966), (750, 115, 0.616, 0.982), (750, 120, 0.724, 0.929), (750, 125, 0.602, 0.856), (751, 130, 0.639, 0.944), (751, 135, 0.560, 0.794), (751, 140, 0.667, 0.639), (751, 145, 0.761, 0.630), (751, 150, 0.745, 0.691), (751, 155, 0.700, 0.630);

-- The mobs: rank 0, attackable, no npcflag, not a guard, every spawn on the same one of the two maps,
-- level inside that map's tuned range.
DROP TEMPORARY TABLE IF EXISTS `dc_tmp_mob_entries`;
CREATE TEMPORARY TABLE `dc_tmp_mob_entries` (`entry` INT UNSIGNED NOT NULL PRIMARY KEY, `map` SMALLINT UNSIGNED NOT NULL, `bucket` TINYINT UNSIGNED NOT NULL) ENGINE=InnoDB;
DELETE FROM `dc_tmp_mob_entries` WHERE `map` = 750;
INSERT INTO `dc_tmp_mob_entries` (`entry`, `map`, `bucket`) SELECT DISTINCT `ct`.`entry`, 750, `ct`.`minlevel` - `ct`.`minlevel` % 5 FROM `creature_template` AS `ct` JOIN `creature` AS `c` ON `c`.`id` = `ct`.`entry` AND `c`.`map` = 750 WHERE `ct`.`rank` = 0 AND `ct`.`minlevel` BETWEEN 80 AND 129 AND `ct`.`npcflag` = 0 AND (`ct`.`unit_flags` & 33555202) = 0 AND `ct`.`name` NOT LIKE '%Guard%' AND `ct`.`name` NOT LIKE '%Sentinel%' AND `ct`.`name` NOT LIKE '%Defender%' AND `ct`.`name` NOT LIKE '%Grunt%' AND NOT EXISTS (SELECT 1 FROM `creature` AS `o` WHERE `o`.`id` = `ct`.`entry` AND `o`.`map` <> 750);
DELETE FROM `dc_tmp_mob_entries` WHERE `map` = 751;
INSERT INTO `dc_tmp_mob_entries` (`entry`, `map`, `bucket`) SELECT DISTINCT `ct`.`entry`, 751, `ct`.`minlevel` - `ct`.`minlevel` % 5 FROM `creature_template` AS `ct` JOIN `creature` AS `c` ON `c`.`id` = `ct`.`entry` AND `c`.`map` = 751 WHERE `ct`.`rank` = 0 AND `ct`.`minlevel` BETWEEN 130 AND 159 AND `ct`.`npcflag` = 0 AND (`ct`.`unit_flags` & 33555202) = 0 AND `ct`.`name` NOT LIKE '%Guard%' AND `ct`.`name` NOT LIKE '%Sentinel%' AND `ct`.`name` NOT LIKE '%Defender%' AND `ct`.`name` NOT LIKE '%Grunt%' AND NOT EXISTS (SELECT 1 FROM `creature` AS `o` WHERE `o`.`id` = `ct`.`entry` AND `o`.`map` <> 751);

-- Keep each mob's modifiers from before the first run (INSERT IGNORE keeps the first copy; the DELETE
-- removes nothing and only satisfies the codestyle rule that every INSERT follows a DELETE).
DELETE FROM `dc_balance_mob_tune_backup` WHERE `entry` = 0;
INSERT IGNORE INTO `dc_balance_mob_tune_backup` (`entry`, `HealthModifier`, `DamageModifier`) SELECT `ct`.`entry`, `ct`.`HealthModifier`, `ct`.`DamageModifier` FROM `creature_template` AS `ct` JOIN `dc_tmp_mob_entries` AS `e` ON `e`.`entry` = `ct`.`entry`;

UPDATE `creature_template` AS `ct` JOIN `dc_tmp_mob_entries` AS `e` ON `e`.`entry` = `ct`.`entry` JOIN `dc_balance_mob_tune_backup` AS `b` ON `b`.`entry` = `ct`.`entry` JOIN `dc_tmp_mob_tune` AS `t` ON `t`.`map` = `e`.`map` AND `t`.`bucket` = `e`.`bucket` SET `ct`.`HealthModifier` = `b`.`HealthModifier` * `t`.`hp_factor`, `ct`.`DamageModifier` = `b`.`DamageModifier` * `t`.`dmg_factor`;

DROP TEMPORARY TABLE `dc_tmp_mob_entries`;
DROP TEMPORARY TABLE `dc_tmp_mob_tune`;
